package at.hausgarten.service;
import org.json.*;import java.util.*;
public class OrderReviewTests {
 static int passed;interface Work{void run()throws Exception;}
 static void check(String name,Work work)throws Exception{work.run();passed++;System.out.println("PASS "+name);}
 static void yes(boolean ok){if(!ok)throw new AssertionError();}
 static void reject(Work w)throws Exception{try{w.run();}catch(Exception expected){return;}throw new AssertionError("Expected rejection");}
 static JSONObject snapshot()throws Exception{return SyntheticBusinessData.object().put("customers",new JSONArray().put(SyntheticBusinessData.object().put("id","qa_c").put("name","QA Kunde").put("active",1))).put("orders",new JSONArray().put(SyntheticBusinessData.object().put("id","qa_o").put("title","Bestand").put("customer_id","qa_c").put("billing_customer_id","qa_c").put("status","Geplant").put("updated_at","2026-10-01T00:00:00Z"))).put("worklogs",new JSONArray()).put("invoices",new JSONArray()).put("photos",new JSONArray());}
 static JSONObject action(String id,String kind,JSONObject row)throws Exception{return SyntheticBusinessData.object().put("client_id",id).put("kind",kind).put("payload",row).put("created_at","2026-10-15T08:00:00Z");}
 static JSONObject bad()throws Exception{return action("bad","order",SyntheticBusinessData.object().put("id","qa_o").put("title","Prüfen").put("customer_id","qa_missing"));}
 static JSONObject state()throws Exception{return SyntheticBusinessData.object().put("master",snapshot()).put("pending",new JSONArray().put(bad()));}
 static JSONObject request(JSONObject state,String decision)throws Exception{return SyntheticBusinessData.object().put("id","qa_o").put("token",OrderReviewRules.token(state)).put("decision",decision).put("order",SyntheticBusinessData.object().put("title","Korrigiert").put("customer_id","qa_c").put("billing_customer_id","qa_c").put("status","In Arbeit").put("description","Explizit geprüft").put("location","Test").put("scheduled_date","").put("customer_visible",1));}
 static JSONObject repair(JSONObject state,String decision)throws Exception{return action("review","order",OrderReviewRules.prepare(state,request(state,decision))).put("created_at","2026-10-15T09:00:00Z");}
 public static void main(String[] args)throws Exception{ SyntheticBusinessData.verify();
  check("inspection is read only and lists completeness and exact reason",()->{JSONObject s=state();String before=s.toString();JSONObject r=OrderReviewRules.inspect(s,"qa_o");yes(s.toString().equals(before));yes(r.getJSONArray("reasons").length()==1);yes(!r.getJSONArray("checks").getJSONObject(1).getBoolean("ok"));});
  check("explicit correction resolves old action without accepting or deleting it",()->{JSONObject s=state(),fix=repair(s,"save"),master=s.getJSONObject("master");JSONArray all=DriveJournalRules.union(s.getJSONArray("pending"),new JSONArray().put(fix));yes(DriveJournalRules.apply(master,all).length()==0);yes(master.getJSONArray("orders").getJSONObject(0).getString("title").equals("Korrigiert"));yes(master.getJSONObject("drive_resolved_actions").has("bad"));yes(!DriveJournalRules.ids(master.getJSONArray("drive_applied_ids")).contains("bad"));yes(all.length()==2);yes(!master.getJSONArray("orders").getJSONObject(0).has("_sync_resolves"));});
  check("keep decision preserves current business fields",()->{JSONObject s=state(),master=s.getJSONObject("master");String title=master.getJSONArray("orders").getJSONObject(0).getString("title");yes(DriveJournalRules.apply(master,DriveJournalRules.union(s.getJSONArray("pending"),new JSONArray().put(repair(s,"keep")))).length()==0);yes(master.getJSONArray("orders").getJSONObject(0).getString("title").equals(title));});
  check("review replay is idempotent and old errors do not return",()->{JSONObject s=state(),master=s.getJSONObject("master");JSONArray all=DriveJournalRules.union(s.getJSONArray("pending"),new JSONArray().put(repair(s,"save")));DriveJournalRules.apply(master,all);String row=master.getJSONArray("orders").toString();yes(DriveJournalRules.apply(master,all).length()==0);yes(master.getJSONArray("orders").toString().equals(row));});
  check("changed data invalidates review token",()->{JSONObject s=state(),r=request(s,"save");s.getJSONObject("master").getJSONArray("orders").getJSONObject(0).put("title","Parallel");reject(()->OrderReviewRules.prepare(s,r));});
  check("bad hash cannot resolve a failed action",()->{JSONObject s=state(),fix=repair(s,"save");fix.getJSONObject("payload").getJSONArray("_sync_resolves").getJSONObject(0).put("sha256","wrong");yes(DriveJournalRules.apply(s.getJSONObject("master"),DriveJournalRules.union(s.getJSONArray("pending"),new JSONArray().put(fix))).length()==2);yes(!s.getJSONObject("master").getJSONObject("drive_resolved_actions").has("bad"));});
  check("invalid corrected customer does not save",()->{JSONObject s=state(),r=request(s,"save");r.getJSONObject("order").put("customer_id","qa_missing");reject(()->OrderReviewRules.prepare(s,r));});
  check("parallel change after review is guarded during journal replay",()->{JSONObject s=state(),fix=repair(s,"save"),master=s.getJSONObject("master");master.getJSONArray("orders").getJSONObject(0).put("description","Parallel");yes(DriveJournalRules.apply(master,DriveJournalRules.union(s.getJSONArray("pending"),new JSONArray().put(fix))).length()==2);yes(!master.getJSONObject("drive_resolved_actions").has("bad"));});
  check("changed resolved historical action fails closed",()->{JSONObject s=state(),master=s.getJSONObject("master");JSONArray all=DriveJournalRules.union(s.getJSONArray("pending"),new JSONArray().put(repair(s,"save")));DriveJournalRules.apply(master,all);all.getJSONObject(0).getJSONObject("payload").put("title","Mutiert");reject(()->DriveJournalRules.apply(master,all));});
  check("other entity or kind cannot be resolved",()->{JSONObject s=state(),fix=repair(s,"save"),other=action("bad","customer",SyntheticBusinessData.object().put("id","qa_o").put("name",""));yes(DriveJournalRules.apply(s.getJSONObject("master"),new JSONArray().put(other).put(fix)).length()==2);});
  check("a valid pending action cannot be suppressed",()->{JSONObject s=state(),fix=repair(s,"save"),valid=action("bad","order",SyntheticBusinessData.object().put("id","qa_o").put("title","Gültig").put("customer_id","qa_c").put("_sync_base",DriveJournalRules.guard(s.getJSONObject("master").getJSONArray("orders").getJSONObject(0),"order")));fix.getJSONObject("payload").getJSONArray("_sync_resolves").getJSONObject(0).put("sha256",OrderReviewRules.actionHash(valid));yes(DriveJournalRules.apply(s.getJSONObject("master"),new JSONArray().put(valid).put(fix)).length()==1);yes(!s.getJSONObject("master").getJSONObject("drive_resolved_actions").has("bad"));});
  check("new unsynchronized order keeps its ID through correction",()->{JSONObject s=SyntheticBusinessData.object().put("master",snapshot()).put("pending",new JSONArray().put(action("new-bad","order",SyntheticBusinessData.object().put("id","qa_new").put("title","").put("customer_id","qa_c").put("_mcp_create",true))));JSONObject r=request(s,"save").put("id","qa_new"),p=OrderReviewRules.prepare(s,r);yes(p.optBoolean("_mcp_create"));yes(DriveJournalRules.apply(s.getJSONObject("master"),DriveJournalRules.union(s.getJSONArray("pending"),new JSONArray().put(action("new-fix","order",p).put("created_at","2026-10-15T09:00:00Z")))).length()==0);yes(s.getJSONObject("master").getJSONArray("orders").length()==2);});
  check("later desktop rejection is held and remains inspectable without a local queue row",()->{JSONObject master=snapshot(),old=master.getJSONArray("orders").getJSONObject(0);JSONObject prior=action("remote-reject","order",SyntheticBusinessData.object(old.toString()).put("title","Vom Import abgelehnt").put("_sync_base",DriveJournalRules.guard(old,"order")));master.put("sync_errors",new JSONArray().put(SyntheticBusinessData.object().put("client_id","remote-reject").put("kind","order").put("error","Fachliche Prüfung am Laptop erforderlich."))).put("drive_applied_ids",new JSONArray().put("remote-reject"));yes(DriveJournalRules.apply(master,new JSONArray().put(prior)).length()==1);yes(master.getJSONArray("orders").getJSONObject(0).getString("title").equals("Bestand"));JSONArray review=DriveJournalRules.reviewActions(master,new JSONArray().put(prior));yes(review.length()==1);JSONObject s=SyntheticBusinessData.object().put("master",master).put("pending",review);JSONObject inspected=OrderReviewRules.inspect(s,"qa_o");yes(inspected.getJSONArray("reasons").getString(0).contains("Laptop"));JSONObject fix=repair(s,"save");JSONArray all=DriveJournalRules.union(review,new JSONArray().put(fix));yes(DriveJournalRules.apply(master,all).length()==0);yes(master.getJSONArray("sync_errors").length()==0&&DriveJournalRules.reviewActions(master,all).length()==0);});
  check("pending work record also protects order customer relation",()->{JSONObject s=state();s.getJSONObject("master").getJSONArray("customers").put(SyntheticBusinessData.object().put("id","qa_d").put("name","Zweiter QA Kunde"));s.getJSONArray("pending").put(action("held-work","worklog",SyntheticBusinessData.object().put("id","qa_w").put("customer_id","qa_c").put("order_id","qa_o").put("hours",-1)));JSONObject r=request(s,"save");r.getJSONObject("order").put("customer_id","qa_d");reject(()->OrderReviewRules.prepare(s,r));});
  check("normal guarded edit after reviewed correction remains replayable",()->{JSONObject s=state(),fix=repair(s,"save"),clean=DriveJournalRules.clean(fix.getJSONObject("payload"));JSONObject next=SyntheticBusinessData.object(clean.toString()).put("title","Danach bearbeitet").put("_sync_base",DriveJournalRules.guard(clean,"order"));JSONArray all=DriveJournalRules.union(s.getJSONArray("pending"),new JSONArray().put(fix).put(action("after-review","order",next).put("created_at","2026-10-15T10:00:00Z")));yes(DriveJournalRules.apply(s.getJSONObject("master"),all).length()==0);yes(s.getJSONObject("master").getJSONArray("orders").getJSONObject(0).getString("title").equals("Danach bearbeitet"));});
  check("portable review canonicalization is independent of platform JSON quoting",()->{String text="ÄÖÜ </script> \u2028 ☘ / \" \n";yes(OrderReviewRules.canonical(text).equals("\"ÄÖÜ </script> \u2028 ☘ / \\\" \\n\""));yes(OrderReviewRules.canonical(-0.0).equals("0"));});
  JSONObject cross=action("hash","order",SyntheticBusinessData.object().put("id","qa_o").put("title","ÄÖÜ </script> \u2028 ☘").put("hours",1.00).put("customer_visible",true));
  System.out.println("CROSS_HASH "+OrderReviewRules.actionHash(cross));
  System.out.println("Passed "+passed+" explicit order review tests.");
 }
}
